function a(){const n=document.getElementById("verifying-loader"),e=document.getElementById("verification-success"),r=document.getElementById("verification-error"),o=document.getElementById("error-message");if(!n)return;const s=new URLSearchParams(window.location.search),t={token:s.get("token"),email:s.get("email")};c(t,{loader:n,success:e,error:r,errorMsg:o})}async function c(n,e){try{const r=window.APP_CONFIG?.baseUrl||"/",s=await(await fetch(`${r}api/verify-account`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(n)})).json();e.loader.classList.add("hidden"),s.success?e.success.classList.remove("hidden"):(e.error.classList.remove("hidden"),e.errorMsg.innerHTML=s.messages?.[0]||"Invalid or expired link.")}catch(r){e.loader.classList.add("hidden"),e.error.classList.remove("hidden"),e.errorMsg.innerText="An unexpected error occurred connecting to the server.",console.error("Verification Error:",r)}}export{a as init};
